import React, { useState, useContext } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';

const Login = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleSubmit = (e) => {
    e.preventDefault();
    login({ email, role: email.includes('admin') ? 'admin' : 'student' });
    navigate('/dashboard');
  };

  return (
    <div className="min-h-screen flex bg-[#0A0E1A]">
      {/* PANNEAU GAUCHE — Branding, visible seulement sur desktop */}
      <div className="hidden lg:flex lg:w-1/2 relative overflow-hidden bg-gradient-to-br from-blue-900/40 via-[#0A0E1A] to-[#0A0E1A] border-r border-slate-800/60 items-center justify-center p-16">
        <div className="absolute top-1/3 left-1/4 w-[400px] h-[400px] bg-blue-600/20 blur-[120px] rounded-full"></div>
        <div className="relative max-w-md">
          <div className="flex items-center gap-2.5 mb-10">
            <div className="w-10 h-10 rounded-lg bg-gradient-to-br from-blue-500 to-cyan-400 flex items-center justify-center font-black text-[#0A0E1A] text-xl shadow-lg shadow-blue-500/20">A</div>
            <span className="text-xl font-extrabold tracking-tight text-white">AVALON <span className="text-blue-400 font-medium">SECURE</span></span>
          </div>
          <h1 className="text-3xl font-bold text-white mb-4 leading-snug">
            Reprends là où tu t'es arrêté.
          </h1>
          <p className="text-slate-400 text-sm leading-relaxed">
            Accède à tes formations, suis ta progression, et continue à monter en compétence sur des scénarios réels de cyberdéfense.
          </p>
        </div>
      </div>

      {/* PANNEAU DROIT — Formulaire, pleine hauteur */}
      <div className="w-full lg:w-1/2 flex items-center justify-center p-6 sm:p-12">
        <div className="w-full max-w-sm">
          <div className="flex lg:hidden items-center gap-2.5 justify-center mb-10">
            <div className="w-9 h-9 rounded-lg bg-gradient-to-br from-blue-500 to-cyan-400 flex items-center justify-center font-black text-[#0A0E1A] text-lg">A</div>
            <span className="text-lg font-extrabold tracking-tight text-white">AVALON <span className="text-blue-400 font-medium">SECURE</span></span>
          </div>

          <h2 className="text-2xl font-bold text-white mb-1">Connexion</h2>
          <p className="text-slate-500 text-sm mb-8">Content de te revoir.</p>

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="text-xs font-semibold text-slate-400 mb-1.5 block">Email</label>
              <input
                type="email"
                placeholder="toi@exemple.com"
                onChange={(e) => setEmail(e.target.value)}
                className="w-full bg-slate-900/60 border border-slate-800 text-white px-4 py-3 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors"
              />
            </div>
            <div>
              <label className="text-xs font-semibold text-slate-400 mb-1.5 block">Mot de passe</label>
              <input
                type="password"
                placeholder="••••••••"
                onChange={(e) => setPassword(e.target.value)}
                className="w-full bg-slate-900/60 border border-slate-800 text-white px-4 py-3 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors"
              />
            </div>
            <button type="submit" className="w-full bg-blue-600 hover:bg-blue-500 text-white font-semibold py-3 rounded-lg text-sm transition-colors mt-2">
              Se connecter
            </button>
          </form>

          <p className="text-center text-slate-500 text-sm mt-8">
            Pas encore de compte ? <Link to="/register" className="text-blue-400 hover:text-blue-300 font-semibold">S'inscrire</Link>
          </p>
        </div>
      </div>
    </div>
  );
};
export default Login;
